import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputLine = scanner.nextLine();
        boolean emailFound = false;
        for (int index = 0; index < inputLine.length(); index++) {
            if (inputLine.charAt(index) == '@') {
                emailFound = true;
            }
        }
        System.out.print(inputLine.charAt(0));
        int idx = 1;
        while (idx < inputLine.length() - 3) {
            if (inputLine.charAt(idx) == 'd' && inputLine.charAt(idx + 1) == 'o' && inputLine.charAt(idx + 2) == 't') {
                System.out.print('.');
                idx += 3;
            } else {
                if (!emailFound && inputLine.charAt(idx) == 'a' && inputLine.charAt(idx + 1) == 't') {
                    System.out.print('@');
                    emailFound = true;
                    idx += 2;
                } else {
                    System.out.print(inputLine.charAt(idx));
                    idx++;
                }
            }
        }
        if (!emailFound && idx + 1 < inputLine.length() - 1 && inputLine.charAt(idx) == 'a' && inputLine.charAt(idx + 1) == 't') {
            System.out.print('@');
            idx += 2;
            if (idx < inputLine.length()) {
                System.out.print(inputLine.charAt(idx));
            }
        } else {
            if (idx < inputLine.length()) {
                System.out.print(inputLine.charAt(idx));
            }
            if (idx + 1 < inputLine.length()) {
                System.out.print(inputLine.charAt(idx + 1));
            }
            if (idx + 2 < inputLine.length()) {
                System.out.print(inputLine.charAt(idx + 2));
            }
        }
        scanner.close();
    }
}
